import os, subprocess, sys, random, math
D = '/tmp/eval_gemm'
SRC = 'gemm.go'
EXE = 'gemm'
BUILD = ['go', 'build', '-o', 'gemm', 'gemm.go']
RUN = [sys.executable, SRC] if BUILD is None else ['./' + EXE]


def fail(msg):
    print('FAIL: ' + msg)
    sys.exit(1)


if not os.path.isfile(os.path.join(D, SRC)):
    fail(SRC + ' not found in ' + D)
os.chdir(D)
_build = None


def start_build():
    global _build
    if BUILD is None:
        return
    if os.path.exists(EXE):
        os.remove(EXE)
    _build = subprocess.Popen(BUILD, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)


def finish_build():
    if _build is None:
        return
    try:
        out, _ = _build.communicate(timeout=25)
    except subprocess.TimeoutExpired:
        _build.kill()
        fail('compile timed out')
    if _build.returncode != 0 or not os.path.isfile(EXE):
        fail('compile failed: ' + out.decode('utf-8', 'replace')[-400:])


def run(inp, limit):
    try:
        p = subprocess.run(RUN, input=inp.encode(), stdout=subprocess.PIPE,
                           stderr=subprocess.DEVNULL, timeout=limit)
    except subprocess.TimeoutExpired:
        fail('solution timed out (limit %gs)' % limit)
    if p.returncode != 0:
        fail('solution exited with status %d' % p.returncode)
    return p.stdout.decode('utf-8', 'replace')


def numbers(text, want, case):
    toks = text.split()
    if len(toks) != want:
        fail('case %d: expected %d output values, got %d' % (case, want, len(toks)))
    try:
        return [float(t) for t in toks]
    except ValueError:
        fail('case %d: unparseable output value' % case)

from operator import mul
GP = 2147483647
GG = 48271


def gm_seq(seed, start, count):
    x = seed * pow(GG, start, GP) % GP
    out = [0] * count
    for t in range(count):
        x = x * GG % GP
        out[t] = x
    return out


def gm_rows(n, seed, rows):
    b = [v / GP for v in gm_seq(seed, n * n, n * n)]
    cols = [b[j::n] for j in range(n)]
    res = {}
    for i in rows:
        a = [v / GP for v in gm_seq(seed, i * n, n)]
        c = [sum(map(mul, a, col)) for col in cols]
        res[i] = (sum(v * v for v in c), max(c))
    return res

LIMIT = 12
rng = random.Random(0x6E33)
seed = lambda: rng.randrange(1, GP)
small = [(1, seed()), (2, seed()), (17, seed()), (100, seed()), (257, seed())]
big_n = 2048
big = (big_n, seed())
big_rows = sorted({0, big_n - 1} | set(rng.sample(range(1, big_n - 1), 10)))
start_build()
want = [gm_rows(n, s, range(n)) for n, s in small]
want_big = gm_rows(big[0], big[1], big_rows)
finish_build()


def check(case, n, s, rows, limit):
    got = numbers(run('%d %d\n' % (n, s), limit), 2 * n, case)
    for i, (S, M) in rows.items():
        for g, w in ((got[2 * i], S), (got[2 * i + 1], M)):
            if not abs(g - w) <= 1e-9 * abs(w) + 1e-12:
                fail('mismatch at case %d' % case)


for c, ((n, s), w) in enumerate(zip(small, want)):
    check(c, n, s, w, LIMIT)
check(len(small), big[0], big[1], want_big, LIMIT)
print('OK: %d hidden cases' % (len(small) + 1))

